const pcBase = 'https://api.canadapost-postescanada.ca/prod/devportal-portaildesdeveloppeurs/';
const pcPostal = /^[ABCEGHJ-NPRSTVXY]\d[ABCEGHJ-NPRSTV-Z]\d[ABCEGHJ-NPRSTV-Z]\d$/;
